import re


_ANCHOR_RE = re.compile(
    r"\bthe\s+item[s]?\s+inspected\s+and\s+the\s+probable\s+violation[s]?\s+(?:is|are)"
    r"(?:\s+as\s+follows)?\s*:",
    re.IGNORECASE,
)
_START_RE = re.compile(r"^\s*1\.\s*(?:$|\S)", re.IGNORECASE)
_STOP_RE = re.compile(r"^\s*(proposed civil penalty|proposed compliance order)\b", re.IGNORECASE)
_CLOSE_RE = re.compile(r"^\s*(respectfully|sincerely|regards|enclosure|cc\b|attachments?)\b", re.IGNORECASE)


def rule_alleged_violations_body_section(doc: dict) -> list[dict]:
    try:
        def norm(text: str) -> str:
            return re.sub(r"\s+", " ", (text or "")).strip()

        def low(text: str) -> str:
            return norm(text).lower()

        lines = [item for item in (doc.get("lines") or []) if isinstance(item, dict)]
        if not lines:
            return []

        # Find the lead-in sentence that introduces the enumerated violations.
        anchor_idx = None
        scan_limit = min(len(lines), 140)
        for i in range(scan_limit):
            for width in range(1, 7):
                if i + width > scan_limit:
                    break
                chunk = " ".join(
                    norm(lines[j].get("text") or "") for j in range(i, i + width) if norm(lines[j].get("text") or "")
                )
                if chunk and _ANCHOR_RE.search(chunk):
                    anchor_idx = i
                    break
            if anchor_idx is not None:
                break

        if anchor_idx is None:
            # Fallback: look for any early line that mentions probable violations.
            for i, item in enumerate(lines[:scan_limit]):
                text = low(item.get("text") or "")
                if "probable violation" in text and "inspect" in text:
                    anchor_idx = i
                    break

        if anchor_idx is None:
            return []

        start_idx = None
        for i in range(anchor_idx, len(lines)):
            if _START_RE.match(norm(lines[i].get("text") or "")):
                start_idx = i
                break

        if start_idx is None:
            return []

        end_idx = len(lines)
        for i in range(start_idx + 1, len(lines)):
            text = low(lines[i].get("text") or "")
            if _STOP_RE.match(text) or _CLOSE_RE.match(text):
                end_idx = i
                break

        item_spans = []
        expected = 1
        for item in lines[start_idx:end_idx]:
            text = norm(item.get("text") or "")
            if not text:
                continue
            if re.fullmatch(r"page\s+\d+\s+of\s+\d+", text.lower()):
                continue
            if re.fullmatch(r"\d+", text):
                continue
            if text.lower().endswith(".docx"):
                continue
            if re.fullmatch(r"cpf\s+\d-\d{4}-\d{3}-nopv", text.lower()):
                continue

            match = re.match(rf"^\s*{expected}\.\s*(?:$|\S)", text)
            if not match:
                continue

            span = {"text": text}
            for key in ("page_no", "line_no", "paragraph_no"):
                if key in item:
                    span[key] = item[key]
            item_spans.append(span)
            expected += 1

        if not item_spans:
            return []

        return item_spans
    except Exception:
        return []

import re


def rule_operator_regulated_part(doc: dict) -> list[dict]:
    try:
        parts_re = re.compile(r"\b(?:49\s*C\.?\s*F\.?\s*R\.?\s*)?(?:Part|part)\s*(192|193|195|199)\b", re.I)
        anchor_re = re.compile(
            r"(subject to|covered by|requirements? of|compliance with|in accordance with|conforms? to|"
            r"required by this part|should have been subject|not subject to|codified in|regulated by)",
            re.I,
        )

        def iter_items():
            for key in ("paragraphs", "lines", "pages"):
                for item in doc.get(key, []) or []:
                    text = (item.get("text") or "").strip()
                    if text:
                        yield key, item, text

        best_candidate = None

        for source, item, text in iter_items():
            if not anchor_re.search(text):
                continue
            for match in parts_re.finditer(text):
                lowered = text.lower()
                specificity = 0
                for phrase in (
                    "subject to",
                    "covered by",
                    "requirements of",
                    "compliance with",
                    "in accordance with",
                    "conforms to",
                    "required by this part",
                    "should have been subject",
                    "not subject to",
                    "codified in",
                    "regulated by",
                ):
                    if phrase in lowered:
                        specificity += 1
                if source == "lines":
                    source_rank = 0
                elif source == "paragraphs":
                    source_rank = 1
                else:
                    source_rank = 2
                word_count = max(1, len(text.split()))

                span = {"text": text}
                for field in ("page_no", "paragraph_no", "line_no"):
                    if field in item:
                        span[field] = item[field]
                span["_source"] = source
                candidate = (word_count, -specificity, source_rank, span.get("page_no", 0), span.get("paragraph_no", 0), span.get("line_no", 0), span)
                if best_candidate is None or candidate < best_candidate:
                    best_candidate = candidate

        if best_candidate is None:
            # Fallback: capture the first nearby sentence-like snippet with a Part citation.
            full_text = doc.get("text") or ""
            for match in parts_re.finditer(full_text):
                start = max(0, match.start() - 140)
                end = min(len(full_text), match.end() + 180)
                snippet = full_text[start:end].strip()
                if anchor_re.search(snippet):
                    return [{"text": snippet}]
            return []

        span = best_candidate[-1]
        span.pop("_source", None)
        return [span]
    except Exception:
        return []
